/// Whether a failed file's write left the run's own incomplete copy at the
/// destination, by the file's identity — its text, or its bytes when its
/// name is not UTF-8 (review cr-jl4fix2-1: two names of one text never
/// share the status): the record's lists, or what this machine's log said.
fn is_left_in_place(
    record: &RunRecord,
    logged: &HashSet<(String, Option<String>)>,
    path: &str,
    raw: Option<&str>,
) -> bool {
    let in_record = match raw {
        Some(raw) => record.left_in_place_raw.iter().any(|left| left == raw),
        None => record.left_in_place.iter().any(|left| left == path),
    };
    in_record || logged.contains(&(path.to_string(), raw.map(str::to_string)))
}

/// What this machine's log of a run says of the files whose write left
/// the run's own incomplete copy, when it was read.
#[derive(Default)]
struct LoggedLeftovers {
    /// A log of the run was found and read.
    read: bool,
    /// Every log of the run here is finished, ends with its `run-end` and
    /// lost nothing: it settles a file's status both ways.
    complete: bool,
    left: HashSet<(String, Option<String>)>,
}

/// The failed files that left the run's own incomplete copy, by identity.
/// Reviews cr-jl4fix3-1, cr-jl4fix4-1: a record from before its lists kept
/// identities filed a raw-named file under its text, so from such a record
/// a raw-named failure whose text is in the text list is ambiguous — its
/// own leftover, or a UTF-8 sibling's. This machine's log settles it: a log
/// that names the exact identity makes it the run's own; a complete log
/// that does not makes it not; an absent or incomplete log leaves it
/// unknowable, and the retry is refused, as when the list is not whole.
fn own_leftovers(
            "this job belongs to machine {}{host}; a job runs only on the machine it was made on",
            spec.machine
        );
    }
    Ok(())
}

/// The command line a job's spec stands for, and its `--files-from` list
/// written out for the run (removed when the returned guard drops).
fn spec_args(
    config_dir: &Path,
    spec: &JobSpec,
) -> Result<(crate::cli::TransferArgs, Option<ListFile>)> {
    // cr-ecm1-4: the arguments below never pass the command line's parser,
    // which is what refuses two options that cannot be taken together.
    if let Some((one, other)) = spec.options.conflict() {
        eyre::bail!("this job asks for both {one} and {other}; a transfer takes only one of them");
    }
    let list = match &spec.files_from {
        Some(lines) => {
            let dir = config_dir.join("jobs");
            std::fs::create_dir_all(&dir)?;
            let name = job_log::new_run_id().map_err(|error| eyre::eyre!("{error}"))?;
            let path = dir.join(format!("files-from-{name}.txt"));
            let mut text = lines.join("\n");
            text.push('\n');
            std::fs::write(&path, text).with_context(|| format!("writing {}", path.display()))?;
            Some(ListFile(path))
        }
        None => None,
    };
    let o = &spec.options;
    let args = crate::cli::TransferArgs {
        source: spec.source.as_arg().to_string(),
        destination: spec.destination.as_arg().to_string(),
        dry_run: o.dry_run,
        checksum: o.checksum,
        size_only: o.size_only,
        ignore_times: o.ignore_times,
        ignore_existing: o.ignore_existing,
        force: o.force,
        delete_scope: o.delete_scope.clone(),
        resume: o.resume,
        drop_windows_metadata: o.drop_windows_metadata,
        retries: o.retries,
        retry_wait: o.retry_wait,
        retry: o.retry,
        wait: o.wait,
        exclude: o.exclude.clone(),
        include: o.include.clone(),
        match_case: o.match_case,
        ignore_case: o.ignore_case,
        files_from: list.as_ref().map(|list| list.0.clone()),
        min_size: o.min_size.clone(),
        max_size: o.max_size.clone(),
        min_age: o.min_age.clone(),
        max_age: o.max_age.clone(),
        force_grpc: o.force_grpc,
        detach: o.detach,
        null: o.null,
        yes: o.yes,
        ..Default::default()
    };
    Ok((args, list))
}

